1: // Algorithm to Calibrate the moisture sensor during the first five seconds.2: // Set the initial values for the minimum and maximum values of the moisture sensor.3: int
MoistureMin ← 400; // The minimum moisture sensor value.4: int
MoistureMax ← 100; // The maximum moisture sensor value.5: while (millisecond () < 5000)6:   {7:   MoistureValue ← analogRead (MoisturePin)8:   // Record the maximum sensor value9:   if (MoistureValue > MoistureMax)10:      {11:        MoistureMax ← MoistureValue12:      }13:   // Record the minimum sensor value14:    if (MoistureValue < MoistureMin)15:    {16:      MoistureMin ← MoistureValue17:     }18:   }19: MoistureValue ← map (MoistureValue, MoistureMin, MoistureMax, 100, 400);
